form {
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

/* ── Form field ────────────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
}

/* ── Checkbox ──────────────────────────────────────────────────── */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin-top: 0.125rem; /* align with first line of label */
  border: 2px solid #6366f1;
  border-radius: 0.25rem;
  background: transparent;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
  position: relative;
}

input[type="checkbox"]:checked {
  background: #6366f1;
  border-color: #6366f1;
}

