input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 5px;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

/* Focus ring — 3:1 against dark background */
input[type="checkbox"]:focus-visible {
  outline: 3px solid #a5b4fc;
  outline-offset: 2px;
}

/* Invalid state */
input[type="checkbox"][aria-invalid="true"] {
  border-color: #f87171;
}

/* ── Label ─────────────────────────────────────────────────────── */
label[for="agree-terms"] {
  font-size: 0.9375rem;
  color: #e2e8f0;
  cursor: pointer;
  line-height: 1.5;
}

label[for="agree-terms"] a {
  color: #a5b4fc;
  text-decoration: underline;
  text-underline-offset: 2px;
}

label[for="agree-terms"] a:hover {
  color: #c7d2fe;
}

label[for="agree-terms"] a:focus-visible {
  outline: 2px solid #a5b4fc;
  outline-offset: 2px;
  border-radius: 2px;
}

/* ── Helper text ───────────────────────────────────────────────── */
.helper-text {
  font-size: 0.8125rem;
  color: #94a3b8;
  padding-left: 1.875rem; /* align under label */
}

/* ── Error text ────────────────────────────────────────────────── */
.error-text {
  font-size: 0.8125rem;
  color: #fca5a5;
  padding-left: 1.875rem;
}

/* ── Submit button ─────────────────────────────────────────────── */
.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: #6366f1;
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid transparent;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn-submit:hover {
  background: #4f46e5;
}

.btn-submit:active {
  transform: scale(0.98);
}

.btn-submit:focus-visible {
  outline: 3px solid #a5b4fc;
  outline-offset: 2px;
}

/* ── Success message ───────────────────────────────────────────── */
.success-message {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 1rem;
  padding: 0.75rem 1rem;
  background: #052e16;
  border: 1px solid #16a34a;
  border-radius: 0.5rem;
  color: #86efac;
  font-size: 0.9375rem;
}

.success-icon {
  flex-shrink: 0;
  color: #4ade80;
}

/* ── Forced colors (Windows High Contrast) ─────────────────────── */
@media (forced-colors: active) {
  input[type="checkbox"] {
    forced-color-adjust: none;
    border: 2px solid ButtonText;
    background: Field;
  }
  input[type="checkbox"]:checked {
    background: Highlight;
    border-color: Highlight;
  }
  input[type="checkbox"]:checked::after {
    border-color: HighlightText;
  }
  .btn-submit {
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
    border-color: ButtonText;
  }
  .btn-submit:hover {
    background: Highlight;
    color: HighlightText;
  }
}

/* ── Reduced motion ────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ── Reflow: narrow viewport ───────────────────────────────────── */
@media (max-width: 360px) {
  .card {
    padding: 1.5rem 1rem;
  }
}
