*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ── Skip link ─────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: #6366f1;
  color: #fff;
  font-weight: 600;
  border-radius: 0 0 0.375rem 0.375rem;
  text-decoration: none;
  transition: top 0.15s;
}
.skip-link:focus {
  top: 0;
}

/* ── Page scaffold ─────────────────────────────────────────────── */
body {
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  background-color: #0f0f17;
  color: #e2e8f0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
}

/* ── Card ──────────────────────────────────────────────────────── */
.card {
  width: 100%;
  max-width: 440px;
  background: #1a1a2e;
  border: 1px solid #2d2d4e;
  border-radius: 1rem;
  padding: 2.5rem 2rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: #f1f5f9;
  letter-spacing: -0.01em;
  margin-bottom: 0.375rem;
}

.intro {
  font-size: 0.9375rem;
  color: #94a3b8;
  margin-bottom: 2rem;
}

/* ── Form ──────────────────────────────────────────────────────── */
form {
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

/* ── Form field ────────────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
}

/* ── Checkbox ──────────────────────────────────────────────────── */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin-top: 0.125rem; /* align with first line of label */
  border: 2px solid #6366f1;
  border-radius: 0.25rem;
  background: transparent;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
  position: relative;
}

input[type="checkbox"]:checked {
  background: #6366f1;
  border-color: #6366f1;
}

/* Checkmark via pseudo-element */
input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 5px;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

/* Focus ring — 3:1 against dark background */
input[type="checkbox"]:focus-visible {
  outline: 3px solid #a5b4fc;
  outline-offset: 2px;
}

/* Invalid state */
input[type="checkbox"][aria-invalid="true"] {
  border-color: #f87171;
}

/* ── Label ─────────────────────────────────────────────────────── */
label[for="agree-terms"] {
  font-size: 0.9375rem;
  color: #e2e8f0;
  cursor: pointer;
  line-height: 1.5;
}

label[for="agree-terms"] a {
  color: #a5b4fc;
  text-decoration: underline;
  text-underline-offset: 2px;
}

label[for="agree-terms"] a:hover {
  color: #c7d2fe;
}

label[for="agree-terms"] a:focus-visible {
  outline: 2px solid #a5b4fc;
  outline-offset: 2px;
  border-radius: 2px;
}

/* ── Helper text ───────────────────────────────────────────────── */
.helper-text {
  font-size: 0.8125rem;
  color: #94a3b8;
  padding-left: 1.875rem; /* align under label */
}

/* ── Error text ────────────────────────────────────────────────── */
.error-text {
  font-size: 0.8125rem;
  color: #fca5a5;
  padding-left: 1.875rem;
}

/* ── Submit button ─────────────────────────────────────────────── */
.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: #4f46e5;
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid transparent;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn-submit:hover {
  background: #4f46e5;
}

.btn-submit:active {
  transform: scale(0.98);
}

.btn-submit:focus-visible {
  outline: 3px solid #a5b4fc;
  outline-offset: 2px;
}

/* ── Success message ───────────────────────────────────────────── */
.success-message {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 1rem;
  padding: 0.75rem 1rem;
  background: #052e16;
  border: 1px solid #16a34a;
  border-radius: 0.5rem;
  color: #86efac;
  font-size: 0.9375rem;
}

.success-icon {
  flex-shrink: 0;
  color: #4ade80;
}

/* ── Forced colors (Windows High Contrast) ─────────────────────── */
@media (forced-colors: active) {
  input[type="checkbox"] {
    forced-color-adjust: none;
    border: 2px solid ButtonText;
    background: Field;
  }
  input[type="checkbox"]:checked {
    background: Highlight;
    border-color: Highlight;
  }
  input[type="checkbox"]:checked::after {
    border-color: HighlightText;
  }
  .btn-submit {
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
    border-color: ButtonText;
  }
  .btn-submit:hover {
    background: Highlight;
    color: HighlightText;
  }
}

/* ── Reduced motion ────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ── Reflow: narrow viewport ───────────────────────────────────── */
@media (max-width: 360px) {
  .card {
    padding: 1.5rem 1rem;
  }
}
